            if state == 'S0':
                if x == 0:
                    z = 0
                    state = 'S0'
                else:
                    z = 1
                    state = 'S1'
            else:
                z = 1 if x == 0 else 0
                state = 'S1'
        out.append({'z': z})
    return out
